sites.find:
spawned = &projectile_pool[result];
spawned->fields.owner_id = owner_id;
spawned->active = 1;
spawned->fields.travel_budget = weapon_table[type_id].travel_budget;
spawned->position = *pos;
spawned->fields.origin = *pos;
spawned->angle = angle;
spawned->fields.type_id = (projectile_type_id_t)type_id;
spawned->fields.life_timer = 0.4f;
spawned->fields.reserved = 0.0f;
spawned->fields.speed_scale = 1.0f;
spawned->fields.velocity.x = (float)(cos(angle) * 1.5f);
spawned->fields.velocity.y = (float)(sin(angle) * 1.5f);

if (type_id == PROJECTILE_TYPE_ION_MINIGUN) {
    spawned->fields.hit_radius = 3.0f;
    spawned->fields.damage_pool = default_damage;
    return result;
}
if (type_id == PROJECTILE_TYPE_ION_RIFLE) {
    spawned->fields.hit_radius = 5.0f;
    spawned->fields.damage_pool = default_damage;
    return result;
}
if (type_id == PROJECTILE_TYPE_ION_CANNON || type_id == PROJECTILE_TYPE_PLASMA_CANNON) {
    spawned->fields.hit_radius = 10.0f;
} else {
    spawned->fields.hit_radius = 1.0f;
    if (type_id == PROJECTILE_TYPE_GAUSS_GUN) {
        spawned->fields.damage_pool = 300.0f;
        return result;
    }
    if (type_id == PROJECTILE_TYPE_FIRE_BULLETS) {
        spawned->fields.damage_pool = 240.0f;
        return result;
    }
    if (type_id == PROJECTILE_TYPE_BLADE_GUN) {
        spawned->fields.damage_pool = 50.0f;
        return result;
    }
}
spawned->fields.damage_pool = default_damage;

